import { describe, expect, it } from "vitest";
import { planCounts } from "./lib";
import assessmentDoc from "../public/demo/assessment.json";
import planDoc from "../public/demo/plan.json";
import type { Assessment, Plan } from "./types";

// Guards the types against the real documents Hermes writes (the demo set is generated by the CLI):
// a field that the UI reads as a string must be a string, and the plan header must match its steps.

describe("demo documents match the UI types", () => {
  it("assessment metadata names providers as objects", () => {
    const a = assessmentDoc as unknown as Assessment;
    expect(typeof a.metadata?.source?.provider).toBe("string");
    expect(typeof a.metadata?.target?.provider).toBe("string");
    expect(a.summary.resource_count).toBe(a.resources.length);
  });
  it("plan summary agrees with its steps", () => {
    const p = planDoc as unknown as Plan;
    const c = planCounts(p);
    expect(c.steps).toBe(p.summary.steps);
    expect(c.approvals).toBe(p.summary.approval_gates);
    expect(c.source).toBe(p.summary.source_impacting_steps);
  });
});
